import{_ as r,l as i,o as a,c as s,v as t,p as l,x as o,d as m,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Mem1 递归上下文重写","description":"","frontmatter":{"title":"Mem1 递归上下文重写","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mem1-context.md","filePath":"llm/mem1-context.md","lastUpdated":1789023840000}'),c={name:"llm/mem1-context.md"};function p(E,e,M,g,u,_){const n=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="mem1-递归上下文重写" tabindex="-1">Mem1 递归上下文重写 <a class="header-anchor" href="#mem1-递归上下文重写" aria-label="Permalink to &quot;Mem1 递归上下文重写&quot;">​</a></h1><div class="epigraph"><p>每一步把「上一内部状态 + 查询 + 新观察」折进一个共享内部状态，然后剪掉旧标签，使长程交互在近乎常数的记忆里继续推理。</p><footer>—— Zhou、Qu、Wu 等，MEM1: Learning to Synergize Memory and Reasoning for Efficient Long-Horizon Agents，arXiv:2506.15841 / ICLR 2026</footer></div><p>Zijian Zhou、Ao Qu、Zhaoxuan Wu、Sunghwan Kim、Alok Prakash、Daniela Rus、Jinhua Zhao、Bryan Kian Hsiang Low、Paul Pu Liang 提出 <strong>MEM1</strong>（Memory-Efficient Mechanism via learning 1-step integrated reasoning and consolidation）：不外挂摘要器，而用强化学习让策略在推理的同一表示里完成巩固。每轮只保留最新的内部状态、查询与观察；上一步的 XML 标签从提示里删除。相对 Qwen2.5-14B-Instruct，在 16 目标多跳 QA 上性能约 \\(3.5\\times\\)、记忆用量约 \\(3.7\\times\\) 更低（相对 14B 峰值 token 与准确率对照）。代码 <code>MIT-MI/MEM1</code>。用户口中的「递归上下文重写」就是这一逐步覆盖，而不是树搜索。本篇写常数记忆与 2D 掩码，不把剪枝写成攻击面。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>长程代理若把所有思维、动作、观察追加进窗口，会得到三条病：推理费用随 \\(N\\) 涨、超出训练长度后分布外、无关 token 稀释注意力。外挂检索/摘要模块与策略分开训练，无法端到端对任务奖励负责。Search-R1、DeepResearcher 等 RL 代理仍常累加全文。MEM1 问：模型能否把巩固当成推理的一部分，使<strong>保留内容由策略决定</strong>，而模块边界消失？</p><p>公开多跳集（HotpotQA、2Wiki、Bamboogle）往往只有两跳，不够逼记忆管理。作者把现有 QA 题交错成 \\(N\\) 目标复合题，强迫多次检索再汇总。另在 WebShop 上测购物导航。MEM1 从 Qwen2.5-7B <strong>Base</strong> 用 PPO 训，指令微调或 SFT 轨迹在他们的比较里更弱。复合题的意义是把「还记得第一个子问题的答案」变成拿分的必要条件：模型若在内部状态里丢掉槽位，后面的检索再准也拼不出满分。</p><h3 id="内部状态是唯一常驻记忆" tabindex="-1">内部状态是唯一常驻记忆 <a class="header-anchor" href="#内部状态是唯一常驻记忆" aria-label="Permalink to &quot;内部状态是唯一常驻记忆&quot;">​</a></h3><p>标注用 XML：内部状态 <code>&lt;IS_t&gt;</code>、环境查询 <code>&lt;query_t&gt;</code>、观察 <code>&lt;info_t&gt;</code>、最终 <code>&lt;answer_t&gt;</code>。步 \\(t+1\\) 把 \\((\\texttt{IS}_t,\\texttt{query}_t,\\texttt{info}_t)\\) 巩固成新的 <code>IS_{t+1}</code>，然后删除步 \\(t\\) 的全部标签。任意时刻提示里大约只有有限个新标签，记忆近乎常数。这与 <a href="/llm/agentfold">AgentFold</a> 保留多块摘要不同：MEM1 是单槽重写，更像覆盖工作记忆。</p><p><span class="marginnote">常数是提示长度的工程近似：内部状态文本仍可随任务变长，只是不再线性堆观察。16 目标上峰值仍略升（表 1：2 目标 \\(6.40\\times10^2\\) token 量级到 16 目标 \\(10.4\\times10^2\\)），不是严格 \\(O(1)\\) 比特。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>滚动时程序化截断：模型一产出查询或答案，宿主就按上一节剪上下文。为避免不知何时停，每轮在状态前插入剩余轮数提示，如 <code>[HINT: YOU HAVE {turns_left} TURNS LEFT]</code>。1–4 目标最多 6 轮，更难任务 20 轮。奖励是可验证的：QA 用精确匹配，WebShop 用环境奖励。<strong>没有</strong>把「短上下文」写进奖励；短是因为截断强迫模型把要的东西写进 <code>IS</code>，否则下一轮看不见，拿不到分。</p><p>训练难点：真实生成时上下文每步在变，PPO 若当一条静态轨迹算对数概率会错。MEM1 把各回合拼成逻辑全轨迹，再加 <strong>2D 注意力掩码</strong>：位置 \\(k\\) 只能看见该步生成时仍保留的 token。另对检索来的外部信息加 1D 掩码，梯度只落在模型自己产生的 token 上。这样 \\(\\rho_k(\\theta)\\) 仍对应「当时真正的条件前缀」。</p>',12)),(a(),l(h,null,{default:o(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IS%5B%22%E5%86%85%E9%83%A8%E7%8A%B6%E6%80%81%20IS_t%22%5D%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%20IS%20%E4%B8%8E%20query%20%E6%88%96%20answer%22%5D%0A%20%20GEN%20--%3E%20ENV%5B%22%E7%8E%AF%E5%A2%83%E8%BF%94%E5%9B%9E%20info_t%22%5D%0A%20%20ENV%20--%3E%20NEW%5B%22%E5%B7%A9%E5%9B%BA%E4%B8%BA%20IS_t%2B1%22%5D%0A%20%20NEW%20--%3E%20PRUNE%5B%22%E5%88%A0%E9%99%A4%E6%AD%A5%20t%20%E7%9A%84%E6%97%A7%E6%A0%87%E7%AD%BE%22%5D%0A%20%20PRUNE%20--%3E%20IS%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[m(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h3 id="_2-目标训练-16-目标仍能用" tabindex="-1">2 目标训练，16 目标仍能用 <a class="header-anchor" href="#_2-目标训练-16-目标仍能用" aria-label="Permalink to &quot;2 目标训练，16 目标仍能用&quot;">​</a></h3><p>在 2 目标增强 QA 上训练，测试 2/8/16 目标。表 1：2 目标 MEM1-QA EM 0.709、F1 0.838，峰值低于 14B 指令模型；8 与 16 目标上 14B 与若干 RL 基线崩溃（红字极低 EM），MEM1 EM 升至 1.97（多目标计数），峰值 \\(10.4\\times10^2\\)，时间 8.70s，而 14B 16 目标 EM 0.567、峰值 \\(38.4\\times10^2\\)、时间 29.7s。文中 \\(3.5\\times\\) / \\(3.7\\times\\) 即此类对照。仅套 MEM1 截断模板而不 RL 的 7B 指令模型，16 目标 EM 仅 0.396——<strong>截断本身不够，要学写状态</strong>。外挂 A-MEM 检索则延迟显著变差（16 目标 91s 级）。</p><p>单目标多跳与 WebShop 上也报了相对 Agent-FLAN、Agent-R、AgentLM 的准确与效率。泛化叙述：训练视野之外的目标数仍升，而全文基线在长度外崩溃。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>推理即记忆：chain-of-thought 被当成工作记忆，从观察里抽出以后还要用的槽。截断把「偷懒依赖全文」从可行集里拿掉，RL 只能把信息搬进 <code>IS</code>。这与人类用填字游戏练选择注意的类比是教学性的，不是神经科学主张。掩码保证优化与推断一致：若训练能看见已剪掉的观察，模型会学一种生产时不存在的捷径。</p><p>失败模式：状态写丢一个约束，后续不可恢复——单槽覆盖没有 <a href="/llm/acm-context">ACM</a> 的 <code>query_memory</code>。状态写入指令式内容会变成持久前缀注入，宿主应对 <code>IS</code> 做长度与内容校验。剩余轮数提示是元数据，换预算要重训或至少重评估。</p><p><span class="marginnote">MEM1 优化的是<strong>题内</strong>工作记忆，不是跨会话用户画像。跨会话应叠加 <a href="/llm/mem0-layer">Mem0</a> / <a href="/llm/zep-graphiti">Zep</a>。ACM 表 1 把 MEM1 标成不可压缩工作上下文、非无损，指的是它不保留原始观察供回查。</span></p><h3 id="复合题的评测陷阱" tabindex="-1">复合题的评测陷阱 <a class="header-anchor" href="#复合题的评测陷阱" aria-label="Permalink to &quot;复合题的评测陷阱&quot;">​</a></h3><p>多目标 EM 是「答对了多少个子问题」一类计数，跨论文比较时要看分母。16 目标上部分基线「峰值不再涨」是因为模型已经崩溃、提前停，不是压缩成功。引用效率必须并列准确率。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>PPO + 2D 掩码对基础设施有要求，不是改一条 prompt。骨干 7B Base，迁到指令模型或别的族要重做。Web QA 从本地 Wikipedia RAG 训、开放网络测，检索器差异会动数字。HINT 轮数泄漏了预算，真实产品若没有硬顶，策略可能不会适时作答。把 MEM1 接到需要引用原始网页片段的合规场景时，必须另存观察日志，因为策略在下一步已经看不见那些标签。</p><p><span class="marginnote">出处：Zhou, Qu, Wu, Kim, Prakash, Rus, Zhao, Low, Liang，<em>MEM1: Learning to Synergize Memory and Reasoning for Efficient Long-Horizon Agents</em>，arXiv:2506.15841，ICLR 2026。<a href="https://github.com/MIT-MI/MEM1" target="_blank" rel="noreferrer">https://github.com/MIT-MI/MEM1</a> 与 <a href="https://mit-mi.github.io/mem1-site/%E3%80%82" target="_blank" rel="noreferrer">https://mit-mi.github.io/mem1-site/。</a></span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MEM1 每步把状态、查询、观察巩固成新内部状态并删除旧标签，近乎常数上下文。</li><li>用 RL（PPO）+ 2D 掩码使训练时的条件前缀与推断截断一致。</li><li>2 目标训练可泛化到 16 目标；相对更大指令模型在长程上又准又省。</li><li>单槽覆盖不可回查原文；需要无损外存时不要单独依赖 MEM1。</li><li>出处：arXiv:2506.15841。</li></ul>',14))])}const B=r(c,[["render",p]]);export{f as __pageData,B as default};
